vector<double> predict(vector<vector<vector<double>>> &input) {

    cout << "Total Layers: " << network.layers.size() << endl;

    vector<double> flattened_input;
    Matrix output;

    for (auto &layer : network.layers) {
        if (layer->type == "SimpleRNN") {
            shared_ptr<SimpleRNNLayer> simpleRNNLayer = dynamic_pointer_cast<SimpleRNNLayer>(layer);
            output = simple_rnn_forward(input, simpleRNNLayer->Wx, simpleRNNLayer->Wh, simpleRNNLayer->brnn);
        } else if (layer->type == "Dense") {
            shared_ptr<DenseLayer> denseLayer = dynamic_pointer_cast<DenseLayer>(layer);
            output = dense_forward(output, denseLayer->weight, denseLayer->bias);
        }
    }

    

    return matrix_to_vector(output);
}

